<?php

declare(strict_types=1);namespace App\Services\TeachingAssignments;use App\Models\{TeachingAssignmentSet,User};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class TeachingAssignmentActivationService {public function activate(User $actor,TeachingAssignmentSet $set):TeachingAssignmentSet{$inspection=app(TeachingAssignmentReadinessService::class)->inspect($set);if(!$inspection['ready'])throw ValidationException::withMessages(['activation'=>'Pembagian tugas belum dapat diaktifkan karena masih ada masalah yang harus diperiksa.']);return DB::transaction(function()use($actor,$set){TeachingAssignmentSet::where('academic_year_id',$set->academic_year_id)->where('status','active')->lockForUpdate()->get()->each(function($old)use($actor){$old->update(['status'=>'archived','active_academic_year_guard'=>null]);activity('teaching-assignments')->causedBy($actor)->performedOn($old)->log("Mengarsipkan set pembagian tugas aktif {$old->name}.");});$set->update(['status'=>'active','active_academic_year_guard'=>$set->academic_year_id,'activated_by'=>$actor->id,'activated_at'=>now()]);activity('teaching-assignments')->causedBy($actor)->performedOn($set)->log("Mengaktifkan Pembagian Tugas Tahun Ajaran {$set->academicYear->name}.");return $set->fresh();});}}
